use crate::ast::{FieldDef, Param, Stmt, TypeRef};

pub fn generate(package: &str, version: &str, program: &[Stmt]) -> String {
    let mut output = format!(
        "# {package} {version} API\n\nGenerated by Nivren {}.\n",
        crate::VERSION
    );
    document_entry_exports(program, &mut output);
    document_modules(program, &mut output);
    output
}

fn document_entry_exports(statements: &[Stmt], output: &mut String) {
    let Some(exports) = statements.iter().find_map(|statement| match statement {
        Stmt::Export { names, .. } => Some(names),
        _ => None,
    }) else {
        return;
    };
    output.push_str("\n## Public API\n\n");
    for export in exports {
        if let Some(declaration) = statements
            .iter()
            .find(|item| declared_name(item) == Some(export))
        {
            output.push_str(&format!("- {}\n", declaration_signature(declaration)));
        }
    }
}

fn document_modules(statements: &[Stmt], output: &mut String) {
    for statement in statements {
        if let Stmt::Module {
            name,
            body,
            exports,
            ..
        } = statement
        {
            output.push_str(&format!("\n## Module `{name}`\n\n"));
            for export in exports {
                if let Some(declaration) =
                    body.iter().find(|item| declared_name(item) == Some(export))
                {
                    output.push_str(&format!("- {}\n", declaration_signature(declaration)));
                }
            }
            document_modules(body, output);
        }
    }
}

fn declared_name(statement: &Stmt) -> Option<&String> {
    match statement {
        Stmt::Let { name, .. }
        | Stmt::Function { name, .. }
        | Stmt::Record { name, .. }
        | Stmt::Enum { name, .. }
        | Stmt::Protocol { name, .. }
        | Stmt::Module { name, .. } => Some(name),
        _ => None,
    }
}

fn declaration_signature(statement: &Stmt) -> String {
    match statement {
        Stmt::Let {
            name, annotation, ..
        } => annotation.as_ref().map_or_else(
            || format!("`keep {name}`"),
            |ty| format!("`keep {name}: {}`", type_name(ty)),
        ),
        Stmt::Function {
            name,
            type_params,
            params,
            return_type,
            needs,
            ..
        } => {
            let generics = if type_params.is_empty() {
                String::new()
            } else {
                format!(
                    "<{}>",
                    type_params
                        .iter()
                        .map(|parameter| parameter.constraint.as_ref().map_or_else(
                            || parameter.name.clone(),
                            |constraint| format!("{}: {constraint}", parameter.name)
                        ))
                        .collect::<Vec<_>>()
                        .join(", ")
                )
            };
            let parameters = params.iter().map(param_name).collect::<Vec<_>>().join(", ");
            let result = return_type
                .as_ref()
                .map(|ty| format!(" gives {}", type_name(ty)))
                .unwrap_or_default();
            let capabilities = if needs.is_empty() {
                String::new()
            } else {
                format!(" needs {}", needs.join(", "))
            };
            format!("`define {name}{generics}({parameters}){result}{capabilities}`")
        }
        Stmt::Record {
            name,
            type_params,
            fields,
            ..
        } => {
            let generics = generic_parameters(type_params);
            let fields = fields.iter().map(field_name).collect::<Vec<_>>().join(", ");
            format!("`shape {name}{generics} {{ {fields} }}`")
        }
        Stmt::Enum {
            name,
            type_params,
            variants,
            ..
        } => {
            let generics = generic_parameters(type_params);
            let variants = variants
                .iter()
                .map(|variant| {
                    variant.payload.as_ref().map_or_else(
                        || variant.name.clone(),
                        |payload| format!("{}({})", variant.name, type_name(payload)),
                    )
                })
                .collect::<Vec<_>>()
                .join(", ");
            format!("`choice {name}{generics} {{ {variants} }}`")
        }
        Stmt::Protocol { name, members, .. } => {
            if members.is_empty() {
                format!("`protocol {name}`")
            } else {
                let members = members
                    .iter()
                    .map(|member| {
                        let parameters = member
                            .params
                            .iter()
                            .map(param_name)
                            .collect::<Vec<_>>()
                            .join(", ");
                        let needs = if member.needs.is_empty() {
                            String::new()
                        } else {
                            format!(" needs {}", member.needs.join(", "))
                        };
                        format!(
                            "define {}({parameters}) gives {}{needs}",
                            member.name,
                            type_name(&member.return_type)
                        )
                    })
                    .collect::<Vec<_>>()
                    .join("; ");
                format!("`protocol {name} {{ {members} }}`")
            }
        }
        Stmt::Module { name, .. } => format!("`module {name}`"),
        _ => "`unknown declaration`".into(),
    }
}

fn generic_parameters(parameters: &[crate::ast::TypeParam]) -> String {
    if parameters.is_empty() {
        String::new()
    } else {
        format!(
            "<{}>",
            parameters
                .iter()
                .map(|parameter| parameter.constraint.as_ref().map_or_else(
                    || parameter.name.clone(),
                    |constraint| format!("{}: {constraint}", parameter.name)
                ))
                .collect::<Vec<_>>()
                .join(", ")
        )
    }
}

fn param_name(param: &Param) -> String {
    param.ty.as_ref().map_or_else(
        || param.name.clone(),
        |ty| format!("{}: {}", param.name, type_name(ty)),
    )
}

fn field_name(field: &FieldDef) -> String {
    format!("{}: {}", field.name, type_name(&field.ty))
}

fn type_name(reference: &TypeRef) -> String {
    match reference {
        TypeRef::Named(name, _) => name.clone(),
        TypeRef::Applied(name, arguments, _) => format!(
            "{name}<{}>",
            arguments
                .iter()
                .map(type_name)
                .collect::<Vec<_>>()
                .join(", ")
        ),
        TypeRef::Array(element, _) => format!("[{}]", type_name(element)),
        TypeRef::Nullable(inner, _) => format!("{}?", type_name(inner)),
        TypeRef::Result(ok, error, _) => {
            format!("Result<{}, {}>", type_name(ok), type_name(error))
        }
    }
}
